Instead of always taking the first empty cell, this version chooses the empty cell with the fewest legal digits. A cell with only one possible value is a much safer choice, and a cell with no values immediately ends the branch.

The masks also make candidate checks quick. The empty cell list is rearranged during recursion, then restored after a failed attempt.

```cpp
#include <vector>
using namespace std;

class Solution {
    vector<int> rowMask, colMask, boxMask;
    vector<pair<int, int> > empty;

    int countBits(int value) {
        int count = 0;
        while (value != 0) {
            value &= value - 1;
            ++count;
        }
        return count;
    }

    bool search(vector<vector<char> >& board, int index) {
        if (index == (int)empty.size()) return true;

        int best = -1;
        int bestChoices = 10;
        int bestMask = 0;

        for (int i = index; i < (int)empty.size(); ++i) {
            int r = empty[i].first;
            int c = empty[i].second;
            int box = (r / 3) * 3 + c / 3;
            int choices = (~(rowMask[r] | colMask[c] | boxMask[box])) & 511;
            int count = countBits(choices);

            if (count < bestChoices) {
                bestChoices = count;
                best = i;
                bestMask = choices;
                if (count == 1) break;
            }
        }

        if (best == -1 || bestChoices == 0) return false;
        swap(empty[index], empty[best]);

        int r = empty[index].first;
        int c = empty[index].second;
        int box = (r / 3) * 3 + c / 3;
        int choices = bestMask;

        while (choices != 0) {
            int bit = choices & -choices;
            int digit = 0;
            while ((1 << digit) != bit) ++digit;

            board[r][c] = (char)('1' + digit);
            rowMask[r] |= bit;
            colMask[c] |= bit;
            boxMask[box] |= bit;

            if (search(board, index + 1)) return true;

            board[r][c] = '.';
            rowMask[r] ^= bit;
            colMask[c] ^= bit;
            boxMask[box] ^= bit;
            choices ^= bit;
        }

        swap(empty[index], empty[best]);
        return false;
    }

public:
    void solveSudoku(vector<vector<char> >& board) {
        rowMask.assign(9, 0);
        colMask.assign(9, 0);
        boxMask.assign(9, 0);
        empty.clear();

        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                if (board[r][c] == '.') {
                    empty.push_back({r, c});
                } else {
                    int bit = 1 << (board[r][c] - '1');
                    int box = (r / 3) * 3 + c / 3;
                    rowMask[r] |= bit;
                    colMask[c] |= bit;
                    boxMask[box] |= bit;
                }
            }
        }
        search(board, 0);
    }
};
```

Edge cases are handled before placing anything. If the board is already complete, `empty` is empty and the search returns immediately. If an empty cell has zero candidates, the function returns false and undoes the previous placement.

Time complexity: `O(9^E)` in the worst case, although choosing the most restricted cell usually cuts down the search a lot.

Space complexity: `O(E)` for recursion and the empty-cell list, plus fixed arrays for the masks. The input board is changed in place.

A direct backtracking version. It scans the board to find the next dot, tries digits from `1` to `9`, and keeps a choice only when the row, column, and 3 x 3 box allow it. A failed choice is changed back to `'.'`.

```cpp
#include <vector>
using namespace std;

class Solution {
public:
    bool canPlace(vector<vector<char> >& board, int row, int col, char digit) {
        for (int i = 0; i < 9; ++i) {
            if (board[row][i] == digit) return false;
            if (board[i][col] == digit) return false;
        }

        int startRow = (row / 3) * 3;
        int startCol = (col / 3) * 3;
        for (int r = startRow; r < startRow + 3; ++r) {
            for (int c = startCol; c < startCol + 3; ++c) {
                if (board[r][c] == digit) return false;
            }
        }
        return true;
    }

    bool search(vector<vector<char> >& board) {
        for (int row = 0; row < 9; ++row) {
            for (int col = 0; col < 9; ++col) {
                if (board[row][col] != '.') continue;

                for (char digit = '1'; digit <= '9'; ++digit) {
                    if (!canPlace(board, row, col, digit)) continue;
                    board[row][col] = digit;
                    if (search(board)) return true;
                    board[row][col] = '.';
                }
                return false;
            }
        }
        return true;
    }

    void solveSudoku(vector<vector<char> >& board) {
        search(board);
    }
};
```

Time complexity: `O(9^E)`, where `E` is the number of empty cells. Each validity check scans only a fixed number of cells.

Space complexity: `O(E)` for the recursion stack. The input board is changed in place.

The empty cells are stored once, and each recursive call works on the next stored position. The row, column, and box data use sets, so checking a candidate reads naturally. When a digit is placed, it is added to all three sets and removed again on backtracking.

For a simple dry run, suppose an empty cell can take only `2` and `8`. The code tries `2` first. If a later cell becomes impossible, `2` is removed from the board and the sets, then `8` gets a chance.

```java
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

class Solution {
    private List<int[]> empty;
    private Set<Character>[] rows;
    private Set<Character>[] cols;
    private Set<Character>[] boxes;

    public void solveSudoku(char[][] board) {
        empty = new ArrayList<>();
        rows = makeSets();
        cols = makeSets();
        boxes = makeSets();

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    empty.add(new int[] {r, c});
                } else {
                    int box = (r / 3) * 3 + c / 3;
                    rows[r].add(board[r][c]);
                    cols[c].add(board[r][c]);
                    boxes[box].add(board[r][c]);
                }
            }
        }
        fill(board, 0);
    }

    @SuppressWarnings("unchecked")
    private Set<Character>[] makeSets() {
        Set<Character>[] result = new HashSet[9];
        for (int i = 0; i < 9; i++) result[i] = new HashSet<>();
        return result;
    }

    private boolean fill(char[][] board, int index) {
        if (index == empty.size()) return true;

        int row = empty.get(index)[0];
        int col = empty.get(index)[1];
        int box = (row / 3) * 3 + col / 3;

        for (char digit = '1'; digit <= '9'; digit++) {
            if (rows[row].contains(digit) || cols[col].contains(digit)
                    || boxes[box].contains(digit)) {
                continue;
            }

            board[row][col] = digit;
            rows[row].add(digit);
            cols[col].add(digit);
            boxes[box].add(digit);

            if (fill(board, index + 1)) return true;

            board[row][col] = '.';
            rows[row].remove(digit);
            cols[col].remove(digit);
            boxes[box].remove(digit);
        }
        return false;
    }
}
```

Time complexity: `O(9^E)` in the worst case. Set lookups are constant time for these small sets.

Space complexity: `O(E)` for the recursion and empty positions, with fixed storage for the 27 sets. The method edits the supplied board instead of returning a new one.

An already solved board needs no recursive guesses, while an unsolvable branch is restored to dots before the next candidate is tried.

The board has only 81 cells, so a small boolean table is enough to remember used digits. `rows[r][d]`, `cols[c][d]`, and `boxes[b][d]` tell whether digit `d` is already taken. This avoids scanning three areas for every trial.

For example, the top-left cell of the middle box has box index `(3 / 3) * 3 + (1 / 3)`, which is `3`. When the board is full, the recursion returns true.

```java
class Solution {
    private boolean[][] rows = new boolean[9][10];
    private boolean[][] cols = new boolean[9][10];
    private boolean[][] boxes = new boolean[9][10];

    public void solveSudoku(char[][] board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.') {
                    int digit = board[r][c] - '0';
                    int box = (r / 3) * 3 + (c / 3);
                    rows[r][digit] = true;
                    cols[c][digit] = true;
                    boxes[box][digit] = true;
                }
            }
        }
        fill(board, 0, 0);
    }

    private boolean fill(char[][] board, int row, int col) {
        if (row == 9) return true;
        if (col == 9) return fill(board, row + 1, 0);
        if (board[row][col] != '.') return fill(board, row, col + 1);

        int box = (row / 3) * 3 + (col / 3);
        for (int digit = 1; digit <= 9; digit++) {
            if (rows[row][digit] || cols[col][digit] || boxes[box][digit]) {
                continue;
            }

            board[row][col] = (char) ('0' + digit);
            rows[row][digit] = true;
            cols[col][digit] = true;
            boxes[box][digit] = true;

            if (fill(board, row, col + 1)) return true;

            board[row][col] = '.';
            rows[row][digit] = false;
            cols[col][digit] = false;
            boxes[box][digit] = false;
        }
        return false;
    }
}
```

Time complexity: `O(9^E)` in the worst case, with constant-time checks for each candidate.

Space complexity: `O(E + 243)`, which is effectively `O(E)` for this fixed board. The board is modified in place.

Edge cases covered here include a puzzle with no empty cells and a cell where every digit is blocked. The latter makes the current branch fail and causes backtracking.

